import Foundation
import os

func handleFile(exists: Bool) -> String {
    let logger = Logger(subsystem: "com.prepstops.app", category: "files")
    if exists {
        logger.info("File opened")
        return "opened"
    } else {
        logger.error("File missing")
        return "missing"
    }
}

print("File status: \(handleFile(exists: false))")

