import Foundation
import os

func validateToken(token: String?) -> Bool {
    let logger = Logger(subsystem: "com.prepstops.auth", category: "security")
    guard let token, !token.isEmpty else {
        logger.fault("Security token corrupted or nil")
        return false
    }
    return true
}

print("Valid token: \(validateToken(token: nil))")

