import Foundation
import os

struct AppLogger {
    static let logger = Logger(subsystem: "com.prepstops.app", category: "general")

    static func logInfo(message: String) {
        logger.info("\(message, privacy: .public)")
        print("Logged: \(message)")
    }
}

AppLogger.logInfo(message: "App launched")

import Foundation

struct NetworkTelemetry {
    func logStatus(code: Int) -> String {
        if code >= 200 && code <= 299 {
            return "Success"
        } else {
            return "Error"
        }
    }
}

let tel = NetworkTelemetry()
print("Response: \(tel.logStatus(code: 404))")

import Foundation

struct PrivacyFilter {
    static func redactSensitive(key: String, value: String) -> String {
        if key == "password" || key == "token" {
            return "[REDACTED]"
        }
        return value
    }
}

print("Token: \(PrivacyFilter.redactSensitive(key: "token", value: "secret123"))")
